protected void onCreate(android.os.Bundle savedInstanceState) {
    super.onCreate(savedInstanceState);
    setContentView(edu.ksu.cs.benign.R.layout.activity_sensitive);
    if (getIntent().hasExtra("status_msg")) {
        java.lang.String status = getIntent().getStringExtra("status_msg");
        if (status.equals("SUCCESS")) {
            android.widget.TextView service_status = (android.widget.TextView) findViewById(edu.ksu.cs.benign.R.id.serviceStatusText);
            service_status.setText("Activity Started from Service");
        }
    }
}
